layout_css:
.sim-container {
  max-width: 820px;
  margin: 0 auto;
  box-sizing: border-box;
}
.sim-top-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.3);
}
.sim-stage-pill {
  display: inline-block;
  background: linear-gradient(135deg, #2563eb, #7c3aed);
  color: #ffffff;
  font-weight: 900;
  font-size: 12px;
  padding: 5px 12px;
  border-radius: 999px;
  letter-spacing: 0.05em;
}
.sim-scoreboard {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}
.sim-score-card {
  padding: 14px;
  border-radius: 12px;
  background: rgba(15, 23, 42, 0.55);
  border: 1px solid rgba(148, 163, 184, 0.3);
  text-align: center;
}
.sim-score-label {
  font-size: 12px;
  opacity: 0.85;
  margin-bottom: 6px;
}
.sim-score-num {
  font-size: 26px;
  font-weight: 900;
  line-height: 1.2;
}
.sim-final-hero {
  padding: 20px;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(30, 41, 59, 0.9), rgba(15, 23, 42, 0.95));
  border: 2px solid #f59e0b;
  text-align: center;
  margin-bottom: 18px;
}
.sim-final-score-big {
  font-size: clamp(34px, 6vw, 54px);
  font-weight: 900;
  color: #facc15;
  text-shadow: 0 0 20px rgba(250, 204, 21, 0.45);
  margin: 6px 0;
}
@keyframes simPop {
  0% { transform: scale(0.85); }
  50% { transform: scale(1.12); }
  100% { transform: scale(1); }
}
.sim-pop-anim {
  animation: simPop 0.35s ease-out;
}
.sim-companion-section {
  margin-bottom: 18px;
}
.sim-companion-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
}
.sim-companion-card {
  width: 100%;
  padding: 12px 16px;
  border-radius: 10px;
  border: 2px solid rgba(148, 163, 184, 0.35);
  background: rgba(15, 23, 42, 0.4);
  color: inherit;
  cursor: pointer;
  transition: all 0.2s;
}
.sim-companion-card.is-selected {
  border-color: #10b981;
  background: rgba(16, 185, 129, 0.15);
  box-shadow: 0 0 12px rgba(16, 185, 129, 0.25);
}
.sim-companion-card.is-locked {
  opacity: 0.45;
  cursor: not-allowed;
}
.sim-comp-badge {
  font-size: 11px;
  padding: 3px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
}
.sim-button-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-bottom: 14px;
}
.sim-btn {
  padding: 14px 16px;
  border-radius: 10px;
  border: none;
  font-weight: 900;
  font-size: 14px;
  cursor: pointer;
  transition: transform 0.1s, opacity 0.2s;
}
.sim-btn:active {
  transform: scale(0.97);
}
.sim-btn-gacha-1 {
  background: linear-gradient(135deg, #3b82f6, #2563eb);
  color: #ffffff;
}
.sim-btn-gacha-10 {
  background: linear-gradient(135deg, #ec4899, #8b5cf6);
  color: #ffffff;
}
.sim-btn-attack {
  width: 100%;
  padding: 18px;
  font-size: 18px;
  background: linear-gradient(135deg, #f59e0b, #ef4444);
  color: #ffffff;
  box-shadow: 0 6px 20px rgba(239, 68, 68, 0.4);
  margin-bottom: 16px;
}
.sim-burst-banner {
  display: none;
  padding: 14px;
  border-radius: 10px;
  background: rgba(234, 179, 8, 0.18);
  border: 1px solid #facc15;
  margin-bottom: 16px;
  text-align: center;
  line-height: 1.6;
}
.sim-log-box {
  max-height: 190px;
  overflow-y: auto;
  padding: 12px;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.45);
  font-family: monospace;
  font-size: 13px;
}
